canvas.addEventListener('pointerdown',e=>{if(ended||!$('intro').hidden)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;const s=squads.find(s=>!s.side&&alive(s).length&&Math.hypot(s.x-x,s.y-y)<35);if(s&&e.button!==2)select(s.id);else issue(x,y);canvas.focus()});canvas.addEventListener('contextmenu',e=>e.preventDefault());$('squads').addEventListener('click',e=>{const b=e.target.closest('[data-squad]');if(b)select(+b.dataset.squad)});$('move').onclick=()=>{mode='move';renderUI()};$('defend').onclick=defend;$('pause').onclick=togglePause;$('begin').onclick=togglePause;$('again').onclick=reset;$('restart').onclick=()=>{if(!started||ended||confirm('Avsluta den här striden och börja om?'))reset()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Ljud på':'Ljud av';$('sound').setAttribute('aria-pressed',String(sound));if(sound){audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();fireSound(600)}};
document.addEventListener('keydown',e=>{if(e.target.closest('button')&&(e.code==='Space'||e.code==='Enter'))return;if(e.code==='Space'){e.preventDefault();togglePause()}if(['1','2','3'].includes(e.key))select(+e.key-1);if(e.key.toLowerCase()==='d')defend();if(e.key.startsWith('Arrow')){e.preventDefault();cursor??={x:squads[selected].x,y:squads[selected].y};if(e.key==='ArrowLeft')cursor.x-=20;if(e.key==='ArrowRight')cursor.x+=20;if(e.key==='ArrowUp')cursor.y-=20;if(e.key==='ArrowDown')cursor.y+=20;cursor.x=Math.max(10,Math.min(1190,cursor.x));cursor.y=Math.max(10,Math.min(790,cursor.y))}if(e.key==='Enter'&&cursor)issue(cursor.x,cursor.y)});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!paused&&!ended){paused=true;renderUI()}});
reset();let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!paused&&!ended)update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
const state=()=>({paused,ended,elapsed:Math.floor(elapsed),capture,selected,squads:squads.filter(s=>!s.side||s.visible).map(s=>({id:s.id,name:s.name,side:s.side,x:Math.round(s.x),y:Math.round(s.y),soldiers:alive(s).length,morale:Math.round(s.morale),order:s.order}))});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_battle',description:'Read the current visible battle state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>state()},{name:'give_move_order',description:'Select a living friendly squad and order movement to map coordinates.',inputSchema:{type:'object',properties:{squad:{type:'integer',minimum:0,maximum:2},x:{type:'number',minimum:10,maximum:1190},y:{type:'number',minimum:10,maximum:790}},required:['squad','x','y'],additionalProperties:false},execute:async a=>{if(!a||!Number.isInteger(a.squad)||a.squad<0||a.squad>2||!Number.isFinite(a.x)||!Number.isFinite(a.y)||a.x<10||a.x>1190||a.y<10||a.y>790||ended||!alive(squads[a.squad]).length)throw Error('Invalid squad, coordinates or battle state');select(a.squad);mode='move';if(!issue(a.x,a.y))throw Error('Order could not be executed');return state()}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
